begin;
create table if not exists public.admin_activity_events(id bigint generated by default as identity primary key,admin_id uuid not null references auth.users(id) on delete cascade,activity_type text not null default 'page',page_path text,device_info text,latitude numeric,longitude numeric,accuracy_m numeric,created_at timestamptz not null default now());
create index if not exists idx_admin_activity_admin_time on public.admin_activity_events(admin_id,created_at desc);alter table public.admin_activity_events enable row level security;
create or replace function public.record_admin_activity(p_activity_type text default 'page',p_page_path text default '',p_device_info text default '',p_latitude numeric default null,p_longitude numeric default null,p_accuracy_m numeric default null) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from customers where id=auth.uid() and is_admin=true and coalesce(blocked,false)=false) then raise exception '관리자 계정이 아닙니다.';end if;insert into admin_activity_events(admin_id,activity_type,page_path,device_info,latitude,longitude,accuracy_m) values(auth.uid(),left(coalesce(p_activity_type,'page'),50),left(coalesce(p_page_path,''),300),left(coalesce(p_device_info,''),200),p_latitude,p_longitude,p_accuracy_m);end;$$;
create or replace function public.get_admin_activity(p_limit integer default 200) returns table(id bigint,admin_id uuid,admin_name text,admin_role text,activity_type text,page_path text,device_info text,latitude numeric,longitude numeric,accuracy_m numeric,created_at timestamptz) language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from customers c where c.id=auth.uid() and c.is_admin=true and coalesce(c.blocked,false)=false and (c.admin_role='developer_admin' or lower(coalesce(c.email,'')) in ('900smk@naver.com','sm0727sm@hanmail.net','p1028p@naver.com'))) then raise exception '개발관리자만 활동기록을 볼 수 있습니다.';end if;return query select e.id,e.admin_id,coalesce(c.business_name,c.owner_name,c.email,'관리자')::text,coalesce(c.admin_role,'admin')::text,e.activity_type,e.page_path,e.device_info,e.latitude,e.longitude,e.accuracy_m,e.created_at from admin_activity_events e join customers c on c.id=e.admin_id order by e.created_at desc limit greatest(1,least(coalesce(p_limit,200),1000));end;$$;
create or replace function public.admin_update_order_party_info(p_order_number text,p_customer_name text,p_owner_name text,p_delivery_name text,p_delivery_phone text,p_delivery_address text,p_memo text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_rows integer;begin if not public.is_inventory_admin() then raise exception '관리자만 주문정보를 수정할 수 있습니다.';end if;if nullif(trim(p_customer_name),'') is null then raise exception '거래처명을 입력하세요.';end if;update orders set customer_name=trim(p_customer_name),customer_owner_name=nullif(trim(p_owner_name),''),delivery_name=coalesce(nullif(trim(p_delivery_name),''),trim(p_customer_name)),delivery_phone=nullif(trim(p_delivery_phone),''),delivery_address=nullif(trim(p_delivery_address),''),memo=nullif(trim(p_memo),'') where order_number=p_order_number;get diagnostics v_rows=row_count;if v_rows=0 then raise exception '주문을 찾을 수 없습니다.';end if;return jsonb_build_object('ok',true,'updated_rows',v_rows);end;$$;
revoke all on function public.record_admin_activity(text,text,text,numeric,numeric,numeric) from public;grant execute on function public.record_admin_activity(text,text,text,numeric,numeric,numeric) to authenticated;revoke all on function public.get_admin_activity(integer) from public;grant execute on function public.get_admin_activity(integer) to authenticated;revoke all on function public.admin_update_order_party_info(text,text,text,text,text,text,text) from public;grant execute on function public.admin_update_order_party_info(text,text,text,text,text,text,text) to authenticated;
commit;
